package com.finance.controller;
import com.finance.model.FinancialGoal;import com.finance.repository.GoalRepository;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;import java.time.LocalDate;import java.util.List;
@RestController @RequestMapping("/api/goals") public class GoalController {private final GoalRepository repo;public GoalController(GoalRepository r){repo=r;}public record Request(@NotBlank String name,@Positive long targetPaise,@PositiveOrZero long savedPaise,LocalDate targetDate){}@GetMapping public List<FinancialGoal> all(Authentication a){return repo.findByUserId(uid(a));}@PostMapping public FinancialGoal create(@Valid @RequestBody Request r,Authentication a){FinancialGoal g=new FinancialGoal();g.setUserId(uid(a));apply(g,r);return repo.save(g);}@PutMapping("/{id}") public FinancialGoal update(@PathVariable String id,@Valid @RequestBody Request r,Authentication a){FinancialGoal g=repo.findByIdAndUserId(id,uid(a)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));apply(g,r);return repo.save(g);}@DeleteMapping("/{id}") public void delete(@PathVariable String id,Authentication a){repo.delete(repo.findByIdAndUserId(id,uid(a)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND)));}private void apply(FinancialGoal g,Request r){g.setName(r.name());g.setTargetPaise(r.targetPaise());g.setSavedPaise(r.savedPaise());g.setTargetDate(r.targetDate());}private String uid(Authentication a){return (String)a.getPrincipal();}}
